package com.hau.ai.domain;import static org.junit.jupiter.api.Assertions.*;import com.hau.ai.domain.exception.InvalidJobTransitionException;import com.hau.ai.domain.model.*;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;class AiJobTest{@Test void validLifecycle(){var j=AiJob.pending(UUID.randomUUID(),UUID.randomUUID(),null,JobType.CHAT,"{}",Instant.now());j.start(Instant.now());j.complete("db:x",Instant.now());assertEquals(JobStatus.COMPLETED,j.status());}@Test void invalidTransitionRejected(){var j=AiJob.pending(UUID.randomUUID(),UUID.randomUUID(),null,JobType.CHAT,"{}",Instant.now());assertThrows(InvalidJobTransitionException.class,()->j.complete("x",Instant.now()));}}
